#define OVW_WORDS 0632

// The writer's labels, as offsets from its origin.
#define OVW_TRACKS   00000    // the survey's two words of track bits
#define OVW_CORE     00002    // an overlay's parameters: the window's full core address,
#define OVW_TRACK    00003    //     its track,
#define OVW_DRUM     00004    //     its drum address,
#define OVW_COUNT    00005    //     the words in its range, 1 to 010000,
#define OVW_SUM      00006    //     and their sum by add
#define OVW_SURVEY   00007    // the survey entr
#define OVW_WRITE    00232    // the write entry
#define OVW_END_RUN  00352    // the end entry when the program follows
#define OVW_END      00347    // the end entry when the tape holds the overlays alone
#define OVW_BUFFER   00632    // the buffer, not punched
#define OVW_SIZE     00672    // the first word past the writer, the core it needs

// Each word as assembled at origin 0 and whether it holds a writer address,
// to which ovlload adds the origin where puts the writer.
typedef struct
{
    uint32_t word;
    uint8_t address;
} OvwWord;

